  const contents = await fs.readdir(currentDir, { withFileTypes: true });

  const uploadPromises = contents
    .filter((item) => item.isFile() && !item.name.startsWith('.'))
    .map((file) => copyFileToS3({ s3, bucket, prefix, buildDir, file: Path.join(subPath, file.name), dryRun }));

  const subDirUploadPromises = contents
    .filter((item) => item.isDirectory())
    .map((dir) => copyDirToS3({ s3, bucket, prefix, buildDir, subPath: Path.join(subPath, dir.name), dryRun }));

